return { json: {
  run_id: previous.run_id,
  started_at: previous.started_at,
  input_summary: previous.input_summary,
  generation_attempts: 2,
  checks: [...previous.checks, { stage: 'provider', attempt: 2, passed: false }],
  status: 'error',
  http_status: 502,
  message: 'The content provider is unavailable. Try again later or contact the operator.',
