const fs = require('fs');
const data = $env.BRIEF_DATA_DIR || '/data';
const result = $json;
const timestamp = new Date().toISOString();
const { run_id, input_summary, status, checks, generation_attempts } = result;

if (status === 'approved' || status === 'needs_review') {
  const path = data + '/packages/' + run_id + '.json';
  const artifact = {
    run_id, timestamp, status, package: result.package ?? null, checks,
    editorial_review: 'pending',
  };
  if (result.candidate) artifact.candidate = result.candidate;
  fs.writeFileSync(path + '.tmp', JSON.stringify(artifact, null, 2) + '\n', { mode: 0o600 });
  fs.renameSync(path + '.tmp', path);
}

const log = {
  timestamp, run_id, input_summary, status, checks, generation_attempts,
  duration_ms: Date.now() - result.started_at,
};
fs.appendFileSync(data + '/runs.jsonl', JSON.stringify(log) + '\n', { mode: 0o600 });

return { json: { http_status: result.http_status,
  response: { run_id, status, package: result.package ?? null, checks, message: result.message },
} };

const { createHash, timingSafeEqual } = require('crypto');
const provided = $json.headers?.['x-api-key'];
const expected = $env.WEBHOOK_API_KEY;
const digest = value => createHash('sha256').update(value).digest();
const authenticated = typeof provided === 'string' && typeof expected === 'string' &&
  expected.length > 0 && timingSafeEqual(digest(provided), digest(expected));

const fs = require('fs');
const data = $env.BRIEF_DATA_DIR || '/data';
const reply = (http_status, response) => ({ json: { http_status, response } });
if (!authenticated) return reply(401, { message: 'Missing or invalid X-API-KEY.' });

const { run_id, decision, note } = $json.body ?? {};
if (typeof run_id !== 'string' || !/^\d{1,20}$/.test(run_id)) {
  return reply(400, { message: 'run_id must be the string returned by the generation webhook.' });
}
if (decision !== 'approve' && decision !== 'request_changes') {
  return reply(400, { message: 'decision must be approve or request_changes.' });
}
if (note !== undefined && (typeof note !== 'string' || [...note.trim()].length > 500)) {
  return reply(400, { message: 'note must be a string of up to 500 characters.' });
}

let artifact;
try {
  artifact = JSON.parse(fs.readFileSync(data + '/packages/' + run_id + '.json', 'utf8'));
} catch (error) {
  if (error.code === 'ENOENT') return reply(404, { message: 'Package not found.' });
  throw error;
}
if (decision === 'approve' && artifact.status !== 'approved') {
  return reply(409, { message: 'Request changes and regenerate a draft that passes automated checks.' });
}

const record = { run_id, decision, note: note?.trim() ?? '', reviewed_at: new Date().toISOString() };
const path = data + '/reviews/' + run_id + '.json';
const temporary = path + '.' + $execution.id + '.tmp';
fs.writeFileSync(temporary, JSON.stringify(record, null, 2) + '\n', { mode: 0o600, flag: 'wx' });
try {
  // A hard link publishes the completed file only if a review does not already exist.
  fs.linkSync(temporary, path);
} catch (error) {
  if (error.code === 'EEXIST') return reply(409, { message: 'A review has already been recorded.' });
  throw error;
} finally {
  fs.unlinkSync(temporary);
}
return reply(200, record);
